const http = require("http");
const net = require("net");
// Node.js's http from an npm package: a server and its clients (keep-alive, chunked bodies,
// headers, POST bodies, errors, raw requests). Prints what it found; the same package under
// Node.js prints the same.
function get(port, path, opts = {}) {
  return new Promise((resolve, reject) => {
    const req = http.request({ host: "127.0.0.1", port, path, ...opts }, (res) => {
      let body = "";
      res.setEncoding("utf8");
      res.on("data", (d) => { body += d; });
      res.on("end", () => resolve({ status: res.statusCode, message: res.statusMessage, headers: res.headers, body, trailers: res.trailers }));
    });
    req.on("error", reject);
    if (opts.body) req.write(opts.body);
    req.end();
  });
}
function raw(port, text) {
  return new Promise((resolve) => {
    const c = net.connect(port, "127.0.0.1", () => c.end(text));
    let got = "";
    c.on("data", (d) => { got += d; });
    c.on("close", () => resolve(got.replace(/Date: .*\r\n/g, "")));
  });
}
module.exports = async function run() {
  const server = http.createServer((req, res) => {
    if (req.url === "/chunked") {
      res.setHeader("Content-Type", "text/plain");
      res.write("part one, ");
      res.addTrailers({ "X-Trailer": "end" });
      res.end("part two");
      return;
    }
    if (req.url === "/json") {
      res.writeHead(201, { "Content-Type": "application/json", "X-Custom": ["a", "b"] });
      res.end(JSON.stringify({ ok: true }));
      return;
    }
    if (req.method === "POST") {
      let body = "";
      req.on("data", (d) => { body += d; });
      req.on("end", () => res.end(`got ${body.length} bytes: ${body.slice(0, 20)} ${req.headers["content-type"]}`));
      return;
    }
    res.end(`${req.method} ${req.url} ${req.httpVersion} ${req.headers.host.replace(/:\d+/, ":PORT")}`);
  });
  await new Promise((r) => server.listen(0, "127.0.0.1", r));
  const { port } = server.address();
  const a = await get(port, "/hello?x=1");
  console.log("get", a.status, a.message, a.body, a.headers["content-length"], a.headers.connection);
  const b = await get(port, "/chunked");
  console.log("chunked", b.body, b.headers["transfer-encoding"], JSON.stringify(b.trailers));
  const c = await get(port, "/json");
  console.log("json", c.status, c.body, c.headers["x-custom"], c.headers["content-type"]);
  const d = await get(port, "/upload", { method: "POST", body: "y".repeat(100000), headers: { "Content-Type": "text/x" } });
  console.log("post", d.body);
  const agent = new http.Agent({ keepAlive: true, maxSockets: 1 });
  const sockets = new Set();
  for (let i = 0; i < 3; i++) {
    await new Promise((resolve) => {
      http.get({ host: "127.0.0.1", port, path: `/k${i}`, agent }, (res) => {
        sockets.add(res.socket.localPort);
        res.resume();
        res.on("end", resolve);
      });
    });
  }
  console.log("keep-alive reused", sockets.size);
  agent.destroy();
  console.log("raw", JSON.stringify(await raw(port, "GET /raw HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n")));
  console.log("bad", JSON.stringify(await raw(port, "BLAH / HTTP/1.1\r\n\r\n")));
  console.log("pipelined", JSON.stringify(await raw(port, "GET /p1 HTTP/1.1\r\nHost: x\r\n\r\nGET /p2 HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n")));
  const head = await get(port, "/head", { method: "HEAD" });
  console.log("head", head.status, JSON.stringify(head.body), head.headers["content-length"]);
  const refused = await get(1, "/").catch((e) => `${e.code} ${e.syscall}`);
  console.log("refused", refused);
  await new Promise((r) => server.close(r));
  console.log("closed");
};
